 const valid=canPlace(state,place.type,place.x,place.z,place.rot,place.moveId);scene.updateGhost(place.x,place.z,valid);if(place.preview)return;if(!valid){toast('Choisis une case libre à l’intérieur de la pièce.','warning');return;}const r=place.moveId?moveObject(state,place.moveId,place.x,place.z,place.rot):buyObject(state,place.type,place.x,place.z,place.rot);if(r.ok){audio.play('place');setView('atelier');ordersOpen=true;selected=r.object?.id||place.moveId;cancelPlacement();scene.setSelected(selected);render(true);autosave();toast(place.moveId?'Nouvelle place, mêmes habitudes.':'L’atelier prend forme.','success');}else toast(r.message,'warning');
