const markupCache=new Map();function paint(id,html){const el=$(id);if(!el)return;const cached=markupCache.get(id);if(cached?.node===el&&cached.html===html)return;if(pointerHeldTarget&&el.contains(pointerHeldTarget))return;if(el.contains(document.activeElement)&&document.activeElement?.matches('input,select,textarea'))return;const scroll=el.scrollTop,scrolls=new Map([...el.querySelectorAll('[data-scroll-key]')].map(n=>[n.dataset.scrollKey,{left:n.scrollLeft,top:n.scrollTop}])),opened=new Map([...el.querySelectorAll('details')].map((d,i)=>[d.dataset.orderDetail||i,d.open]));el.innerHTML=html;el.scrollTop=scroll;el.querySelectorAll('[data-scroll-key]').forEach(n=>{const saved=scrolls.get(n.dataset.scrollKey);if(saved){n.scrollLeft=saved.left;n.scrollTop=saved.top;}});el.querySelectorAll('details').forEach((d,i)=>{const key=d.dataset.orderDetail||i;if(opened.has(key))d.open=opened.get(key);});markupCache.set(id,{node:el,html});}
function toast(text,kind='info'){const el=document.createElement('div');el.className='toast '+kind;el.innerHTML=icon(kind==='success'?'check':kind==='warning'?'wrench':'spool',18)+'<span>'+esc(text)+'</span>';$('#toasts').append(el);setTimeout(()=>el.remove(),5500);}
function autosave(manual=false){try{state.savedAt=new Date().toISOString();localStorage.setItem(SAVE_KEY,exportSave(state));$('#save-indicator').innerHTML='<i></i> '+(manual?'Partie sauvegardée':'Sauvegarde locale');if(manual)toast('Partie sauvegardée sur cet appareil. Pense à exporter pour la transférer.','success');}catch(e){toast('Sauvegarde locale indisponible. Exporte ta partie pour la conserver.','warning');}}
function modal(title,body,wide=false){avatarPreview?.dispose();avatarPreview=null;$('#modal-content').innerHTML=`<div class="modal-head"><div><span class="eyebrow">LE CARNET FILAMENT</span><h2 id="modal-title">${title}</h2><div id="modal-ticker" class="modal-ticker"></div></div><button class="icon-button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div>${body}`;$('#modal').className=wide?'wide':'';if(!$('#modal').open)$('#modal').showModal();renderHeader();}
function closeModal(){avatarPreview?.dispose();avatarPreview=null;if($('#modal').open)$('#modal').close();}
$('#modal').addEventListener('close',()=>{avatarPreview?.dispose();avatarPreview=null;});
function act(result,success){if(!result)return;if(result.ok){if(success)toast(success,'success');render(true);autosave();}else toast(result.message,'warning');}
function setView(v){
 stockOpen=false;creationsOpen=false;pilotOpen=false;ordersOpen=false;selected=null;scene.setSelected(null);view=v;const panel=!['atelier','build'].includes(v);$('#game-panel').hidden=!panel;$('.shop-section').hidden=v!=='build';$('#other-view').hidden=false;
 $('#panel-title').textContent=({orders:'Le carnet des commandes',stock:'La réserve à bobines',marketing:'La vitrine de l’atelier',finance:'La petite comptabilité',journal:'Les nouvelles du jour'})[v]||'Le carnet';
 $('#panel-symbol').innerHTML=icon(v==='build'?'bench':v,23);$('#breadcrumb-title').textContent=NAV.find(x=>x[0]===v)?.[1]||'Atelier';
 document.querySelectorAll('.nav-item').forEach(b=>{const active=b.dataset.view===v;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 document.body.dataset.panel=panel?v:v==='build'?'build':'none';if(panel){cancelPlacement();ordersOpen=false;}render(true);scene.resize();
}
function duration(mins){return mins>=60?num(mins/60,1)+' h':num(mins)+' min';}
function deadline(o){const d=(o.due-state.time)/1440;return d<0?`Retard de ${num(-d,1)} j`:d<1?'Échéance dans '+duration(o.due-state.time):'Pour le jour '+(dayOf(o.due)+1);}
function orderCard(o,full=false){const compatible=compatiblePrinters(state,o).length;const available=filamentStock(state,o.material,o.colorId),required=!o.fromStock&&['request','design','queued','loading'].includes(o.status),missing=Math.max(0,o.grams-available),service=o.salesKind==='service'||['Sur mesure','Professionnel','Fichier client'].includes(o.category);const product=PRODUCTS.find(p=>p.id===o.product),progress=o.total?Math.max(0,Math.min(100,100*(1-o.remaining/o.total))):0;const needs=o.status==='queued'&&available<o.grams;
 let actions='';if(o.status==='request')actions=`<button class="button primary small" data-action="accept" data-id="${o.id}">Confirmer ${icon('arrow',14)}</button><button class="text-button" data-action="decline" data-id="${o.id}">Décliner</button>`;
 else if(o.status==='ready')actions=`<button class="button primary small" data-action="ship" data-id="${o.id}">${icon('truck',15)} Expédier</button>`;
 else if(!['paid','shipping','cancelled','expired'].includes(o.status))actions=`<span class="order-status ${needs?'danger':''}">${needs?'Filament insuffisant':STATUS[o.status]}</span><button class="text-button subtle" data-action="cancel-order" data-id="${o.id}" aria-label="Annuler la commande ${o.number}">Annuler</button>`;
 else actions=`<span class="order-status ${o.status==='paid'?'good':''}">${STATUS[o.status]}${o.status==='paid'&&!o.paidOut?' · versement en attente':''}</span>`;
 return `<article class="order-card ${o.status==='request'?'request':''}"><div class="order-top"><span class="channel ${o.channel==='etsy'?'etsy':''}">${o.isPrototype?'Prototype':o.channel==='etsy'?'Etsy':o.channel==='local'?'Client direct':'Boutique'}</span><span>#${o.number} · ${o.isPrototype?'Atelier':service?'Prestation':'Objet'}</span><strong>${money(o.price)}</strong></div><div class="order-product"><div class="product-mini ${product?.id||'pot'}" style="--product-color:${esc(o.color)}">${icon(o.category==='Sur mesure'?'wrench':o.product==='pot'?'spool':'stock',28)}</div><div><h3>${esc(o.name)}${o.qty>1?' ×'+o.qty:''}</h3><p>${esc(o.client)} <span>· ${esc(o.category)}</span></p></div></div>${o.fromStock?`<div class="order-ready-stock">✓ ${o.qty} exemplaire(s) déjà fabriqués · prélevés du stock après confirmation</div>`:''}<div class="order-filament"><i class="filament-dot" style="--filament:${colorFor(o.colorId).hex}"></i><span><b>${o.material.toUpperCase()} · ${colorFor(o.colorId).name}</b><small>${num(o.grams)} g ${required?'requis · '+num(available)+' g en stock':'déjà engagés'}</small></span>${required&&missing>0?`<button data-action="add-needed" data-material="${o.material}" data-color="${o.colorId}" data-grams="${missing}" title="Ajouter les bobines au panier">＋ ${num(missing)} g</button>`:required?'<em>✓ Disponible</em>':''}</div><details class="order-more" data-order-detail="${o.id}-fabrication" ${(o.parcel||o.recipe)?'':'hidden'}><summary>Fabrication et colis</summary>${o.parcel?`<div class="order-parcel">${o.parcel.pickup?'Remise en main propre':'Colis '+o.parcel.tier} · ${o.parcel.dimensions.join(' × ')} mm · ${num(o.parcel.weight,2)} kg · emballage estimé ${money(o.parcel.packaging)}</div>`:''}${o.recipe?`<div class="order-slicing"><span>${num(o.recipe.part)} g de pièce + ${num(o.recipe.supports)} g de supports + ${num(o.recipe.waste)} g de purge</span><small>${o.recipe.brief} · remplissage ${o.recipe.infill} % · ${o.dimensions.join(' × ')} mm</small></div>`:''}</details>${required&&!compatible?'<div class="order-compatibility">'+(printers(state).length?'Plateau ou profil à adapter avant fabrication.':'Prévois une imprimante pour fabriquer cette pièce.')+'</div>':''}<div class="order-meta"><span>${num(o.grams)} g ${o.material.toUpperCase()}</span><span>${o.fromStock?'Déjà imprimé':num(o.hours,1)+' h machine'}</span><span>${o.fromStock?15:num((o.design+o.finish+.42)*60)} min perso.</span></div>${!['paid','cancelled','expired'].includes(o.status)?`<div class="order-deadline ${o.due<state.time?'danger':''}">${icon('clock',13)} ${deadline(o)}${o.status==='request'?(o.channel==='local'?'<span>Retrait sur place</span>':'<span>+ '+money(o.shipping)+' port</span>'):''}</div>`:''}${['design','printing','finish','packing','loading'].includes(o.status)?`<div class="tiny-progress"><i style="width:${progress}%"></i></div>`:''}<div class="order-actions">${actions}</div>${full&&o.settlement?`<details data-order-detail="${o.id}"><summary>Détail de la vente</summary><dl class="mini-facts"><div><dt>Vente et port</dt><dd>${money(o.settlement.gross)}</dd></div><div><dt>Frais du canal</dt><dd>−${money(o.settlement.fees)}</dd></div><div><dt>Provision sociale/fiscale</dt><dd>−${money(o.settlement.tax)}</dd></div><div><dt>Transport</dt><dd>−${money(o.settlement.shipping)}</dd></div><div><dt>Versement net</dt><dd>${money(o.settlement.net)}</dd></div></dl><small>Matière, énergie, emballage et structure sont comptés séparément.</small></details>`:''}</article>`;
}
function portrait(a){const fox=a.kind==='fox';return `<svg viewBox="0 0 72 78" aria-hidden="true"><path d="M14 77q0-26 22-26t22 26" fill="${a.sweater}" stroke="#f5e1b8" stroke-width="2" stroke-dasharray="2 3"/>${fox?`<path d="M14 25 12 5 30 17M42 17 60 5 58 28" fill="${a.skin}" stroke="#f0ceac" stroke-width="3"/>`:''}<ellipse cx="36" cy="33" rx="23" ry="25" fill="${a.skin}"/>${a.hat!=='none'?`<path d="M12 25Q11 1 35 3q26 0 25 22Z" fill="${a.hatColor}" stroke="#f3d4af" stroke-width="2"/><path d="M12 24h48" stroke="${a.hatColor}" stroke-width="8" stroke-linecap="round"/>`:`<path d="M14 25Q12 0 38 5q21 1 21 19l-9-6-12 4-12-5Z" fill="${a.hair}"/>`}<ellipse cx="27" cy="35" rx="3" ry="4" fill="#3d453b"/><ellipse cx="45" cy="35" rx="3" ry="4" fill="#3d453b"/><path d="M30 47q6 6 12 0" fill="none" stroke="#93695b" stroke-width="2" stroke-linecap="round"/>${a.glasses?'<g fill="none" stroke="#695c50" stroke-width="2"><circle cx="27" cy="35" r="8"/><circle cx="45" cy="35" r="8"/><path d="M35 35h2"/></g>':''}</svg>`;}
function renderHeader(){
 const c=clock(state.time),m=metrics(state),all=lifetimeKpis(state),work=presence(state).canWork,p=presence(state),a=normalizeAppearance(state.appearance);$('#day-label').textContent=DAYS[c.weekday]+' · jour '+c.day;$('#clock-label').textContent=c.time;$('#day-medallion').textContent=c.hour>=7&&c.hour<20?'☀':'☾';$('#presence').textContent=presence(state).label;$('#presence').className='pill '+(work?'green':'muted');
 paint('#time-controls',timeControls(speed,lastSpeed));
 $('#time-scale').textContent=speed===0?'Une petite pause dans l’atelier.':'1 min réelle = '+num(speed/60)+' h dans le jeu';
 paint('#kpis',[['Caisse',money(state.cash),'Disponible, hors provision de '+money(state.taxReserve),'finance'],['CA / jour',money(all.averageRevenue),'Moyenne par jour calendaire depuis le début, jours vides inclus.','stock'],['Les machines',m.busy+' / '+m.printers,m.active+' commande(s) en cours','printer'],['Bénéfice / jour',money(all.averageProfit),'Résultat moyen par jour, après coûts et provisions.','finance']].map(([label,value,note,ic],i)=>`<button class="kpi kpi-${i}" data-action="${i===2?'machine-dashboard':'nav'}" data-view="${i===3?'marketing':'finance'}" title="${esc(note)}"><span class="resource-icon">${icon(ic,18)}</span><span class="resource-data"><small>${label}</small><strong>${value}</strong></span></button>`).join(''));
 paint('#avatar-portrait',portrait(a));$('#avatar-name').textContent=a.name;$('#avatar-button em').textContent='Maîtrise · '+masteryInfo(state).label;if($('#skills-live'))paint('#skills-live',skillsPanel(state));const skill=$('#skill-button b');if(skill)skill.textContent=skillPoints(state).available;const ticker=$('#modal-ticker');if(ticker)paint('#modal-ticker',`<span><i class="${speed?'is-live':''}"></i> J${c.day} · ${c.time} · ${speed?'L’atelier continue':'En pause'}</span><button data-action="pause">${speed?'Pause':'Reprendre'}</button>`);renderAudioStatus();renderLife();renderStockWidgets();renderPilot();renderCreations();$('#mail-count').textContent=m.requests+' demande'+(m.requests>1?'s':'')+' · '+m.active+' en cours';$('#mail-badge').textContent=m.requests+m.active;$('#orders-toggle').setAttribute('aria-expanded',String(ordersOpen));
 paint('#worker-hud',atelierPulse(state));syncChrome();

}
function renderRight(){const target=$('#orders-panel');target.hidden=!ordersOpen;if(!ordersOpen)return;const m=metrics(state),obj=state.objects.find(x=>x.id===selected);if(obj){const spec=specFor(obj),p=spec?.kind==='printer',job=state.orders.find(o=>o.id===obj.job);paint('#orders-panel',`<div class="panel-title"><div><span class="eyebrow">DANS LA PIÈCE</span><h2>${esc(spec?.name||'Bureau de départ')}</h2></div><button class="icon-button" data-action="deselect" aria-label="Fermer le détail">${icon('close',18)}</button></div><div class="equipment-portrait ${p?'is-printer':''}">${icon(p?'printer':obj.type==='rack'?'spool':obj.type==='photo'?'photo':'bench',68)}<span>${p?obj.broken?'À réparer':job?'En activité':'Disponible':'À sa place'}</span></div>${p?`<div class="equipment-health"><div><span>État général</span><b>${num(obj.condition)} %</b></div><div class="health-track"><i style="width:${obj.condition}%"></i></div></div><dl class="mini-facts"><div><dt>Heures imprimées</dt><dd>${num(obj.runHours,1)} h</dd></div><div><dt>Depuis l’entretien</dt><dd class="${obj.runHours-obj.serviceHours>realismFor(state).maintenanceHours?'danger':''}">${num(obj.runHours-obj.serviceHours)} / ${realismFor(state).maintenanceHours} h</dd></div><div><dt>Âge calendaire</dt><dd>${num((state.time-obj.purchased)/1440)} jours</dd></div><div><dt>Travail en cours</dt><dd>${job?'#'+job.number:'Aucun'}</dd></div></dl>${obj.broken?`<div class="inline-notice warning">${esc(PARTS[obj.broken].name)} en panne. Remplace cette pièce pour repartir.</div>`:''}${machineModes(obj)}${machineQuickStats(state,obj)}<div class="equipment-interventions"><button class="button secondary" data-action="service" data-id="${obj.id}" ${obj.job?'disabled':''}>${icon('wrench',16)} Entretien · 6 € / 30 min</button>${Object.entries(PARTS).map(([id,v])=>`<button class="part-button" data-action="part" data-id="${obj.id}" data-part="${id}" ${obj.job||state.parts[id]===0?'disabled':''}><span>${v.name}<small>${num(obj.partHours[id])} h d’usage · repère ${v.life} h</small></span><span>${state.parts[id]>0?'Installer '+icon('arrow',14):'À commander'}</span></button>`).join('')}</div><p class="fine-print">Les repères de pièces sont des seuils de jeu ; inspection et état priment. Une machine entretenue n’est pas condamnée à cinq ans.</p>`:`<p class="equipment-description">${esc(spec?.desc||'Ordinateur, bureau et petit outillage sont disponibles au démarrage. Le travail de conception se fait ici.')}</p>`}<div class="equipment-actions"><button class="button ghost" data-action="move" data-id="${obj.id}">${icon('grid',16)} Déplacer</button>${obj.type!=='desk'?`<button class="text-button" data-action="sell" data-id="${obj.id}">Revendre · ${money(obj.paid*.5*(obj.condition??100)/100)}</button>`:''}</div>`);return;}
 const list=state.orders.filter(o=>!o.isStock).filter(o=>rightTab==='requests'?o.status==='request':!['request','paid','cancelled','expired'].includes(o.status)).sort((a,b)=>a.due-b.due);
 const scroll=target.querySelector('.orders-scroll')?.scrollTop||0;paint('#orders-panel',`<div class="panel-title"><div><span class="eyebrow">ÇA SE PASSE À L’ATELIER</span><h2>Le carnet de commandes</h2></div><span class="count-pill">${m.active+m.requests}</span></div><div class="segmented"><button data-action="right-tab" data-tab="requests" class="${rightTab==='requests'?'active':''}">Demandes <span>${m.requests}</span></button><button data-action="right-tab" data-tab="active" class="${rightTab==='active'?'active':''}">En cours <span>${m.active}</span></button></div><div class="orders-scroll">${list.length?list.slice(0,12).map(o=>orderCard(o)).join(''):`<div class="empty-state">${icon(rightTab==='requests'?'marketing':'stock',38)}<h3>${rightTab==='requests'?'Une journée plus calme.':'La place est libre.'}</h3><p>${rightTab==='requests'?'Les demandes arrivent de manière aléatoire. Prépare ton stock ou fais connaître l’atelier.':'Confirme une demande pour lancer la première fabrication.'}</p>${rightTab==='requests'?'<button class="button ghost" data-action="nav" data-view="marketing">Faire connaître l’atelier</button>':''}</div>`}</div><div class="panel-foot">${icon('clock',15)}<span>Accepter engage ton atelier. Décliner une demande n’abaisse pas ta note.</span></div>`);target.querySelector('.orders-scroll').scrollTop=scroll;
}
function shopIcon(item){return item.kind==='printer'?'printer':item.id==='rack'?'spool':item.id==='photo'?'photo':item.id==='plant'?'leaf':'bench';}
function shopIllustration(item){
 const p=item.kind==='printer',colors={fdm:'#e4d5ae',enclosed:'#a5bb97',pro:'#9faea1',bench:'#c2a17a',packing:'#d0ac7f',rack:'#9cae88',photo:'#b3a4b3',plant:'#8fa377'},c=colors[item.id]||'#b6b38d';
 const table='<path d="m18 42 39-8 31 12-39 10Z" fill="#cfa977" stroke="#ac8a61" stroke-width="2"/><path d="m22 45 0 22m59-20v20M48 56v16" stroke="#7b8b6b" stroke-width="5" stroke-linecap="round"/>';
 let picture=p?table+`<path d="m34 13 29-4 15 9v25l-28 7-16-8Z" fill="${c}" stroke="#9c9b7c" stroke-width="2"/><path d="m39 20 24-4 11 5v20l-23 5-12-7Z" fill="#8a9b83"/><path d="M40 21v19l11 5V24l22-4M53 35l18-4" fill="none" stroke="#eee3bc" stroke-width="3"/><path d="m52 31 7-2 4 4-8 2Z" fill="#d08c6d"/><circle cx="51" cy="8" r="9" fill="#dfb98c" stroke="#efe0b8" stroke-width="3"/><circle cx="51" cy="8" r="3" fill="#af946e"/>`:item.id==='bench'?table+'<path d="m32 43 23-4 14 6-24 5Z" fill="#91a483" stroke="#b9c29a" stroke-width="2"/><path d="m43 41 2 8m7-10 2 8m-16-1 23-4" stroke="#d4d6ac"/>':item.id==='packing'?table+'<path d="m40 25 21-4 12 8v17l-23 6-10-8Z" fill="#e5c694" stroke="#b9996a" stroke-width="2"/><path d="m40 25 10 9 23-5m-23 5v18" fill="none" stroke="#b9996a" stroke-width="2"/>':item.id==='rack'?'<path d="M29 13v57m47-57v57M29 26h47M29 44h47M29 61h47" fill="none" stroke="#8a9a78" stroke-width="5" stroke-linecap="round"/>'+[22,40,58].map((y,i)=>[39,57,72].map((x,j)=>`<circle cx="${x}" cy="${y}" r="6" fill="${['#d39c78','#9eb491','#b3a1b7'][(i+j)%3]}" stroke="#e7d6ac" stroke-width="2"/>`).join('')).join(''):item.id==='photo'?'<path d="m31 65 18-45 18 45M49 21v44" stroke="#8c9277" stroke-width="3" stroke-linecap="round"/><rect x="36" y="14" width="27" height="18" rx="5" fill="#9b9684" stroke="#dbccac" stroke-width="2"/><circle cx="50" cy="23" r="6" fill="#6c7b6b"/><path d="M77 68V25" stroke="#a3a58b" stroke-width="3"/><rect x="65" y="9" width="24" height="24" rx="5" fill="#f2e4c1" stroke="#d1bc92" stroke-width="2"/>':'<path d="M34 50h35l-4 21H39Z" fill="#cf9877" stroke="#b78965" stroke-width="2"/><path d="M50 54V19" stroke="#7e9669" stroke-width="4"/><ellipse cx="43" cy="31" rx="9" ry="19" transform="rotate(-25 43 31)" fill="#9ab381"/><ellipse cx="60" cy="33" rx="8" ry="20" transform="rotate(28 60 33)" fill="#7f9e72"/><ellipse cx="51" cy="20" rx="7" ry="15" fill="#a9bc8c"/>';
 return `<svg viewBox="0 0 104 80" aria-hidden="true"><ellipse cx="55" cy="71" rx="33" ry="5" fill="#9a8451" opacity=".12"/>${picture}</svg>`;
}
function renderShop(){const scroll=$('#shop').scrollLeft;paint('#shop',SHOP.map(i=>`<button class="shop-card ${placement===i.id?'chosen':''}" data-action="buy-mode" data-type="${i.id}" title="${esc(i.desc)}"><div class="shop-drawing ${i.id}">${shopIllustration(i)}<span class="shop-add">+</span></div><small>${i.tag}</small><b>${i.name}</b>${i.kind==='printer'?`<em class="shop-machine-volume">${i.volume.join(' × ')} mm</em>`:'<em class="shop-machine-volume">Pour ton atelier</em>'}<span class="shop-price">${money(i.price)} <i>${state.objects.filter(o=>o.type===i.id).length||'+'}</i></span></button>`).join(''));$('#shop').scrollLeft=scroll;}
function renderEquipmentStrip(){
 $('#equipment-strip').innerHTML=state.objects.map(o=>`<button class="equipment-chip ${selected===o.id?'selected':''}" data-action="select" data-id="${o.id}" title="${esc(specFor(o)?.name||'Bureau')}">${icon(specFor(o)?.kind==='printer'?'printer':o.type==='rack'?'spool':o.type==='photo'?'photo':'bench',14)}<span>${specFor(o)?.name||'Bureau'}</span>${o.broken?'<i class="dot danger"></i>':o.job?'<i class="dot green"></i>':''}</button>`).join('');
 const machine=printers(state).length>0,done=state.metrics.completed,step=machine?(done?3:2):1;$('#first-steps').hidden=done>=8;
 $('#first-steps').innerHTML=`<span class="quest-star">${done?'✦':'✿'}</span><div><small>LE PETIT OBJECTIF · ${step} / 3</small><b>${!machine?'Une première machine':!done?'Ta première création':'Un atelier qui grandit'}</b><p>${!machine?'Pose une imprimante pour commencer.':!done?'Confirme une demande, puis prépare son colis.':done+' / 8 commandes livrées avant ta propre boutique.'}</p></div><button class="quest-action" data-action="${!machine?'buy-mode':!done?'show-active':'nav'}" ${!machine?'data-type="fdm"':'data-view="marketing"'} aria-label="${!machine?'Installer ma première imprimante':!done?'Voir mes commandes':'Voir ma boutique'}">${icon('arrow',18)}</button>`;
}
function beginPlacement(type,id=null){placement=type;moveId=id;rot=id?(state.objects.find(o=>o.id===id)?.rot||0):0;setView('atelier');placement=type;moveId=id;scene.setPlacement(type,rot,id);$('#placement-banner').hidden=false;$('#placement-banner').innerHTML=`<div>${icon('grid',18)}<b>${id?'Déplacer':'Placer'} · ${esc(SHOP.find(i=>i.id===type)?.name||'Bureau')}</b><small>Clique au sol · R pour tourner</small></div><div><button class="button small" data-action="rotate-object">Tourner</button><button class="button primary small" data-action="open-grid">Choisir une case</button><button class="icon-button" data-action="cancel-placement" aria-label="Annuler le placement">${icon('close',17)}</button></div>`;renderShop();}
function cancelPlacement(){placement=null;moveId=null;rot=0;scene.setPlacement(null);$('#placement-banner').hidden=true;}
function gridModal(){if(!placement){toast('Choisis d’abord un équipement dans la boutique.');return;}modal(moveId?'Déplacer l’équipement':'Choisir sa place',`<p class="modal-lead">Vue du dessus de la pièce. Les cases claires sont libres. L’achat est débité quand tu valides une case.</p><div class="grid-legend"><i></i> Libre <i class="occupied"></i> Occupé <span>${esc(SHOP.find(x=>x.id===placement)?.name||'Bureau')} · rotation ${rot*90}°</span></div><div class="floor-grid">${Array.from({length:48},(_,i)=>{const x=i%8,z=Math.floor(i/8),ok=canPlace(state,placement,x,z,rot,moveId);return `<button data-action="grid-place" data-x="${x}" data-z="${z}" aria-label="Case ${x+1}, ${z+1}" ${!ok?'disabled':''}>${x+1}<small>${z+1}</small></button>`;}).join('')}</div><div class="modal-actions"><button class="button ghost" data-action="grid-rotate">Tourner l’objet</button><button class="button primary" data-action="close-modal">Retour à la 3D</button></div>`,true);}
function sparkChart(rows,fields,height=220){if(!rows.length)return `<div class="chart-empty">${icon('finance',35)}<b>Les premiers chiffres arrivent à minuit.</b><span>Aucune courbe inventée : ton activité dessine la suite.</span></div>`;const w=760,h=height,pad=42,all=rows.flatMap(r=>fields.map(f=>r[f.key]||0)),max=Math.max(1,...all),min=Math.min(0,...all),span=max-min;const x=i=>pad+(rows.length===1?.5:i/(rows.length-1))*(w-pad*1.4),y=v=>h-30-(v-min)/span*(h-55);return `<div class="financial-chart"><svg role="img" aria-label="${esc(fields.map(f=>f.label).join(', '))} par jour simulé" viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet">${[0,.5,1].map(t=>{const v=min+t*span;return `<line x1="${pad}" y1="${y(v)}" x2="${w-12}" y2="${y(v)}" stroke="#e6e7df" stroke-dasharray="3 5"/><text x="${pad-9}" y="${y(v)+4}" text-anchor="end" fill="#89938c" font-size="11">${num(v)}</text>`;}).join('')}${fields.map(f=>`<path d="${rows.map((r,i)=>(i?'L':'M')+x(i)+','+y(r[f.key]||0)).join(' ')}" fill="none" stroke="${f.color}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>${rows.length===1?`<circle cx="${x(0)}" cy="${y(rows[0][f.key]||0)}" r="4" fill="${f.color}"/>`:''}`).join('')}<text x="${pad}" y="${h-5}" fill="#89938c" font-size="11">${rows[0].label||'Jour '+rows[0].day}</text><text x="${w-12}" y="${h-5}" text-anchor="end" fill="#89938c" font-size="11">${rows.at(-1).label||'Jour '+rows.at(-1).day}</text></svg><div class="chart-legend">${fields.map(f=>`<span><i style="background:${f.color}"></i>${f.label}</span>`).join('')}</div></div>`;}
function ordersPage(){const m=metrics(state),groups=[['request','Nouvelles demandes'],['production','À l’atelier'],['delivery','Expéditions et livraisons'],['history','Dernières commandes terminées']];return `<div class="view-intro"><div class="inline-notice">${icon('clock',20)}<div><b>La capacité compte davantage que la taille du carnet.</b><p>${m.active} commande${m.active>1?'s':''} active${m.active>1?'s':''} · ${m.late} en retard · ${m.requests} demandes à examiner. Les délais incluent fabrication et transport.</p></div></div><div class="automation-bar"><label><input type="checkbox" data-setting="autoAccept" ${state.settings.autoAccept?'checked':''}> Confirmer automatiquement sous capacité</label><label><input type="checkbox" data-setting="autoShip" ${state.settings.autoShip?'checked':''}> Préparer les envois automatiquement</label></div></div>${groups.map(([id,title])=>{let list=state.orders.filter(o=>!o.isStock).filter(o=>id==='request'?o.status==='request':id==='production'?['design','queued','loading','printing','finish','packing'].includes(o.status):id==='delivery'?['ready','shipping'].includes(o.status):['paid','cancelled'].includes(o.status));if(id==='history')list=list.slice(-12).reverse();return `<section class="page-section"><div class="section-heading"><h2>${title} <span class="count-pill">${list.length}</span></h2></div>${list.length?`<div class="orders-grid">${list.map(o=>orderCard(o,true)).join('')}</div>`:'<div class="empty-line">Aucune commande dans cette étape pour le moment.</div>'}</section>`;}).join('')}`;}
function stockPage(){return stockInterface(state,basket,draft)+`<section class="page-section"><div class="section-heading"><h2>Les pièces de rechange</h2><p>On remplace une pièce, pas systématiquement une machine.</p></div><div class="parts-grid">${Object.entries(PARTS).map(([id,v])=>`<article class="part-card"><span class="part-illustration">${icon(id==='nozzle'?'printer':'wrench',31)}</span><h3>${v.name}</h3><p>${state.parts[id]} en stock · ${duration(v.work*60)} de pose</p><div><b>${money(v.price)}</b><button class="button ghost small" data-action="supply" data-kind="part" data-item="${id}">Commander</button></div></article>`).join('')}</div></section>`;}
function marketingPage(){return storefrontPage(state,shopMode);}
function recentFinancePage(){const m=metrics(state),rows=state.daily.slice(-30),expense=state.books.filter(x=>x.at>=state.time-30*1440&&x.kind!=='revenue'),names={materials:'Filament consommé',energy:'Électricité',packaging:'Emballage',maintenance:'Entretien et pièces',overhead:'Structure & logiciels',depreciation:'Amortissement machines',marketing:'Communication',selling:'Frais de vente',tax:'Provision sociale et fiscale',logistics:'Transport'};const totals=Object.entries(names).map(([key,label])=>({label,value:expense.filter(x=>x.kind===key).reduce((a,x)=>a+x.amount,0)})).sort((a,b)=>b.value-a.value),max=Math.max(1,...totals.map(t=>t.value));return `<div class="finance-summary"><article><span>Résultat d’activité · 30 j</span><strong class="${m.profit<0?'danger':'good'}">${money(m.profit)}</strong><p>CA comptabilisé moins consommation, frais, amortissements et provisions.</p></article><article><span>Après ton temps personnel</span><strong>${money(m.economicProfit)}</strong><p>${num(m.human,1)} h valorisées à ${num(realismFor(state).hourValue)} €/h. Ce coût d’opportunité n’est pas un salaire décaissé.</p></article><article><span>Versements clients en attente</span><strong>${money(m.pendingPayout)}</strong><p>Paiement du canal 2 jours après livraison. La caisse arrive après le CA.</p></article></div><div class="finance-grid"><section class="white-card"><div class="section-heading"><h2>CA, coûts et bénéfice</h2><span class="pill">30 jours simulés</span></div>${sparkChart(rows,[{key:'revenue',label:'CA',color:'#427b69'},{key:'cost',label:'Coûts',color:'#d28a65'},{key:'profit',label:'Bénéfice',color:'#8882a9'}])}</section><section class="white-card"><h2>Ce que coûtent les couches</h2><div class="cost-bars">${totals.map(t=>`<div><span>${t.label}</span><b>${money(t.value)}</b><i style="width:${t.value/max*100}%"></i></div>`).join('')}</div></section></div><div class="finance-grid"><section class="white-card"><h2>La caisse au fil des jours</h2>${sparkChart(rows,[{key:'cash',label:'Caisse disponible',color:'#427b69'}],200)}</section><section class="white-card"><h2>Travailler, puis se payer.</h2><dl class="mini-facts"><div><dt>Caisse disponible</dt><dd>${money(state.cash)}</dd></div><div><dt>Provision mise à part</dt><dd>${money(state.taxReserve)}</dd></div><div><dt>Réserve minimale d’achat</dt><dd>${money(state.settings.reserve)}</dd></div><div><dt>Objectif de retrait mensuel</dt><dd>${money(state.settings.monthlyDraw)}</dd></div><div><dt>Retraits personnels cumulés</dt><dd>${money(state.totalOwnerDraw)}</dd></div><div><dt>Commandes livrées</dt><dd>${state.metrics.completed}</dd></div><div><dt>Impressions ratées</dt><dd>${state.metrics.failedPrints}</dd></div></dl><button class="button ghost" data-action="settings">Régler ma rémunération</button></section></div><div class="inline-notice">${icon('finance',22)}<div><b>Le stock et les machines ne sont pas du bénéfice.</b><p>Les achats de stock sortent de la caisse ; la matière est passée en coût quand elle est consommée. Les machines sont amorties sur 5 ans, sans être détruites à cette date. Modèle de jeu sans gestion détaillée de TVA, de prêts ni de fiscalité du foyer.</p></div></div><section class="page-section white-card"><div class="section-heading"><h2>Le journal de caisse</h2><button class="button ghost small" data-action="export-ledger">${icon('download',15)} CSV</button></div><div class="table-scroll"><table><thead><tr><th>Moment</th><th>Mouvement</th><th>Catégorie</th><th>Montant</th></tr></thead><tbody>${state.cashLedger.slice(-35).reverse().map(r=>`<tr><td>J${dayOf(r.at)+1} · ${clock(r.at).time}</td><td>${esc(r.label)}</td><td>${esc(CASH_LABELS[r.kind]||r.kind)}</td><td class="${r.amount<0?'':'good'}">${r.amount>0?'+':''}${money(r.amount)}</td></tr>`).join('')||'<tr><td colspan="4">Aucun mouvement. Les 1 500 € sont ton apport, pas du CA.</td></tr>'}</tbody></table></div></section>`;}
function financePage(){const tabs=financeTabs(financeMode);if(financeMode==='machines')return tabs+machineDashboard(state);if(financeMode==='recent')return tabs+recentFinancePage();const rows=state.analytics.monthly.map(m=>({...m,label:'Mois '+(m.month+1)}));return tabs+lifetimeSummary(state)+`<section class="white-card lifetime-chart"><h2>CA, coûts et bénéfice par mois simulé</h2>${sparkChart(rows,[{key:'revenue',label:'CA',color:'#849b64'},{key:'cost',label:'Coûts',color:'#c08e68'},{key:'profit',label:'Bénéfice',color:'#9a8d9d'}])}</section>`;}
function journalPage(){return `<div class="journal-layout"><section class="white-card"><div class="section-heading"><h2>Ce qui vient de se passer</h2><span class="pill">${state.log.length} événements</span></div><div class="event-list">${state.log.map(e=>`<article class="event ${e.type}"><span class="event-symbol">${icon(e.type==='client'?'orders':e.type==='warning'?'wrench':e.type==='success'?'check':'spool',17)}</span><div><small>JOUR ${dayOf(e.at)+1} · ${clock(e.at).time}</small><p>${esc(e.text)}</p></div></article>`).join('')}</div></section><aside class="white-card journal-note"><span class="eyebrow">PRENDRE DU RECUL</span><h2>Quelques repères.</h2><p>Une journée vide n’est pas un bug. Les demandes sont aléatoires, et acheter une imprimante ne crée pas de clients.</p><p>Les impressions peuvent continuer la nuit. Le travail humain attend le prochain créneau disponible.</p><p>Tu peux refuser une demande avant de t’engager. Les annulations et les retards après confirmation affectent les avis.</p><button class="button ghost" data-action="guide">Lire les règles ${icon('arrow',16)}</button></aside></div>`;}
function renderOther(){const panel=$('#other-view'),scroll=panel.scrollTop,opened=new Set([...panel.querySelectorAll('details[open]')].map(el=>el.dataset.orderDetail));paint('#other-view',({orders:ordersPage,stock:stockPage,marketing:marketingPage,finance:financePage,journal:journalPage}[view]||ordersPage)());panel.scrollTop=scroll;panel.querySelectorAll('details').forEach(el=>{if(opened.has(el.dataset.orderDetail))el.open=true;});}
function render(force=false){if(force)presentation.capture(state,performance.now());renderHeader();if(!force&&document.activeElement?.matches('input,select,textarea'))return;renderRight();if(force){renderShop();renderEquipmentStrip();}if(!['atelier','build'].includes(view))renderOther();}
function swatches(key,label){const names={skin:'Teint ou pelage',hair:'Cheveux',sweater:'Pull en laine',pants:'Pantalon',hatColor:'Couvre-chef'};return `<fieldset class="color-choice" data-color-group="${key}" ${key==='hair'&&state.appearance.kind==='fox'||key==='hatColor'&&state.appearance.hat==='none'?'hidden':''}><legend>${label||names[key]}</legend><div>${PALETTES[key].map((color,i)=>`<button class="color-swatch" style="--swatch:${color}" data-action="appearance-color" data-field="${key}" data-color="${color}" aria-label="${names[key]} · couleur ${i+1}" aria-pressed="${state.appearance[key]===color}"><span>✓</span></button>`).join('')}</div></fieldset>`;}
function character(){state.appearance=normalizeAppearance(state.appearance);const a=state.appearance;modal('Un artisan à ton image.',`<div class="character-workshop"><section class="character-display"><div class="character-pin">COUSU AVEC AMOUR</div><div id="character-preview" class="character-preview" aria-label="Aperçu 3D de mon personnage"></div><div class="character-preview-controls"><button class="button ghost small" data-action="rotate-character">${icon('rotate',15)} Tourner</button><span>Une petite peluche, un grand savoir-faire.</span></div></section><form class="character-options" onsubmit="return false"><label class="character-name">Le petit nom<input aria-label="Nom du personnage" data-appearance="name" maxlength="24" value="${esc(a.name)}"></label><fieldset class="style-choice"><legend>Qui est à l’atelier ?</legend><div><button type="button" data-action="appearance-choice" data-field="kind" data-value="human" aria-pressed="${a.kind==='human'}">☺ Artisan</button><button type="button" data-action="appearance-choice" data-field="kind" data-value="fox" aria-pressed="${a.kind==='fox'}">❧ Petit renard</button></div></fieldset>${swatches('skin')}${swatches('hair')}${swatches('sweater')}${swatches('pants')}<fieldset class="style-choice"><legend>Le couvre-chef</legend><div>${[['beanie','Bonnet'],['cap','Casquette'],['wizard','Petit mage'],['none','Sans']].map(([v,label])=>`<button type="button" data-action="appearance-choice" data-field="hat" data-value="${v}" aria-pressed="${a.hat===v}">${label}</button>`).join('')}</div></fieldset>${swatches('hatColor')}<div class="character-accessories"><label><input type="checkbox" data-appearance="apron" ${a.apron?'checked':''}> Tablier de l’atelier</label><label><input type="checkbox" data-appearance="glasses" ${a.glasses?'checked':''}> Petites lunettes</label></div>${masteryPanel(state)}</form></div><div class="modal-actions"><span class="fine-print">La tenue est gratuite et conservée avec ta partie.</span><button class="button primary" data-action="close-modal">C’est tout moi ! ${icon('check',17)}</button></div>`,true);$('#modal').classList.add('character-modal');avatarPreview=new CharacterPreview($('#character-preview'),a,scene.materialFor);}
function updateAppearance(key,value){const next={...state.appearance,[key]:value};if(key==='kind'&&value==='fox'&&state.appearance.kind!=='fox')next.skin='#d99553';if(key==='kind'&&value==='human'&&state.appearance.kind!=='human')next.skin=DEFAULT_APPEARANCE.skin;state.appearance=normalizeAppearance(next);avatarPreview?.setAppearance(state.appearance);document.querySelectorAll('[data-color-group]').forEach(el=>el.hidden=(el.dataset.colorGroup==='hair'&&state.appearance.kind==='fox')||(el.dataset.colorGroup==='hatColor'&&state.appearance.hat==='none'));document.querySelectorAll('[data-action="appearance-color"]').forEach(el=>el.setAttribute('aria-pressed',String(state.appearance[el.dataset.field]===el.dataset.color)));document.querySelectorAll('[data-action="appearance-choice"]').forEach(el=>el.setAttribute('aria-pressed',String(state.appearance[el.dataset.field]===el.dataset.value)));renderHeader();autosave();}

function guide(){modal('Le quotidien d’un petit atelier.',`<div class="guide-intro"><span class="guide-emblem">${icon('spool',62)}</span><p>1 500 €, une pièce et une activité à construire. Le mode idle avance à un rythme conseillé de <b>4 à 5 minutes réelles par jour simulé</b>. Tu gardes le contrôle des vitesses et des consignes.</p></div><div class="guide-grid"><section><b>01 / Le pilote te seconde</b><p>Active « Atelier autonome », puis coche les tâches que tu souhaites déléguer. Le pilote vérifie la capacité, les couleurs et la réserve. Il n’achète jamais de nouvelles imprimantes tout seul.</p></section><section><b>02 / Chaque travail consomme sa matière</b><p>La masse dépend de la taille, du remplissage, des supports et des purges. Le volume du plateau doit convenir. Ce sont des estimations de tranchage, pas le résultat d’un véritable fichier STL.</p></section><section><b>03 / Les temps creux servent à créer</b><p>Recherche des modèles commercialisables ou conçois tes produits. Un prototype physique doit être réussi avant l’ajout au catalogue. Le développement et la fabrication respectent tes horaires.</p></section><section><b>04 / L’argent suit les livraisons</b><p>Le stock est payé à l’achat et consommé en fabrication. Les clients directs retirent leurs pièces ; les ventes expédiées supportent du transport et des frais de canal. L’électricité est facturée mensuellement sans compter la charge deux fois.</p></section></div><details class="guide-details"><summary>Repères de marché et conventions</summary><p>Les machines sont des modèles réels avec des tarifs de référence issus des catalogues constructeurs. Le meuble à 45 €, les consommations moyennes, les probabilités de raté et les coefficients de vitesse sont des hypothèses du jeu. Une vitesse maximale de déplacement ne permet pas de prévoir seule la durée d’impression. Les anciennes machines gardent leurs valeurs et performances.</p><p>Les créations originales peuvent être proposées sur Etsy. Un modèle tiers nécessite une autorisation commerciale et reste ici limité aux clients directs et à ta boutique. Les patrons découverts dans le jeu sont fictifs ; aucun fichier réel n’est téléchargé. Chercher des modèles ne crée aucun revenu garanti.</p><p>Ta boutique coûte 0 € à créer et à héberger dans la simulation, grâce à tes compétences, mais nécessite 8 h de travail. Frais de fonctionnement de l’atelier : 80 €/mois, hors matière, transport et énergie. Provision sociale et fiscale réglable ; TVA et fiscalité du foyer simplifiées.</p><p>Sources consultées le 13 novembre 2026 : <a href="https://bambulab-eu.myshopify.com/collections/3d-printer" target="_blank" rel="noopener">Catalogue Bambu EU ↗</a> · <a href="https://www.prusa3d.com/fr/produit/prusa-core-one-kit-advanced-filtration-bundle/" target="_blank" rel="noopener">Prusa CORE One+ ↗</a> · <a href="https://www.etsy.com/legal/creativity/" target="_blank" rel="noopener">Créations sur Etsy ↗</a> · <a href="https://help.prusa3d.com/article/where-can-you-get-3d-models_2179" target="_blank" rel="noopener">Modèles et droits ↗</a> · <a href="https://pro.prusa3d.com/guides/how-to-build-a-3d-printing-farm/" target="_blank" rel="noopener">Modèles d’activité ↗</a>.</p></details><div class="modal-actions"><button class="button secondary" data-action="machine-compare">Comparer les machines</button><button class="button primary" data-action="close-modal">Retour à l’atelier</button></div>`,true);}
function settings(){openSettings('realism');}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function renderAudioStatus(){const b=$('#sound-button');if(!b)return;b.classList.toggle('sound-muted',!audio.prefs.enabled);b.setAttribute('title',audio.status());const text=$('#audio-status');if(text)text.textContent=audio.status();}
function showSounds(){openSettings('sounds');}
function showLife(first=false){if(!first){openSettings('life');return;}modal('Ton atelier, dans ta vraie vie.',lifeForm(state,true),true);$('#modal').classList.add('life-modal');}
function renderStockWidgets(){const quote=quoteBasket(basket,state.settings);$('#stock-checkout-bar').hidden=!quote.ok;if(quote.ok)paint('#stock-checkout-bar',`<span><b>${quote.qty} bobine(s) · ${money(quote.total)}</b><small>Port commun : ${money(quote.shipping)}</small></span><button class="button primary" data-action="cart-checkout">Valider la livraison</button>`);paint('#stock-glance',compactStock(state,basket));$('#stock-popup').hidden=!stockOpen;if(stockOpen&&!document.activeElement?.matches('#stock-popup input,#stock-popup select')){const target=$('#stock-popup-content'),scroll=target.scrollTop;paint('#stock-popup-content',stockInterface(state,basket,draft));target.scrollTop=scroll;}}
function openStock(){setView('atelier');stockOpen=true;creationsOpen=false;pilotOpen=false;renderCreations();renderPilot();renderStockWidgets();}
function addBasket(material,colorId,qty=1){if(!stockOpen)setView('atelier');const found=basket.find(l=>l.item===material&&l.colorId===colorId);if(found)found.qty=Math.min(12,found.qty+qty);else basket.push({kind:'filament',item:material,colorId,qty:Math.min(12,qty)});stockOpen=true;render(true);audio.play('click');}
function restock(){const needs=stockNeeds(state).filter(n=>n.missing>0);for(const n of needs){const existing=basket.find(l=>l.item===n.material&&l.colorId===n.colorId),qty=Math.ceil(n.missing/1000);if(existing)existing.qty=Math.max(existing.qty,qty);else basket.push({kind:'filament',item:n.material,colorId:n.colorId,qty});}openStock();if(!needs.length)toast('Les couleurs nécessaires sont déjà disponibles ou commandées.');}
function renderPilot(){paint('#idle-bar',automationBar(state));$('#pilot-panel').hidden=!pilotOpen;if(pilotOpen&&!document.activeElement?.matches('#pilot-panel input')){const scroll=$('#pilot-panel .pilot-content')?.scrollTop||0;paint('#pilot-panel',pilotPanel(state));const content=$('#pilot-panel .pilot-content');if(content)content.scrollTop=scroll;}}
document.addEventListener('pointerdown',e=>{pointerHeldTarget=e.target;if(e.target.closest('#creations-panel'))creationPointerDown=true;},{capture:true});
for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>{creationPointerDown=false;pointerHeldTarget=null;},{capture:true});
function renderCreations(){const panel=$('#creations-panel');panel.hidden=!creationsOpen;if(!creationsOpen||creationPointerDown||document.activeElement?.matches('#creations-panel input,#creations-panel select'))return;const scroll=panel.querySelector('.creations-content')?.scrollTop||0;paint('#creations-panel',creationsPanel(state,creationsTab));const content=panel.querySelector('.creations-content');if(content)content.scrollTop=scroll;}
function openCreations(tab=null){setView('atelier');cancelPlacement();creationsOpen=true;pilotOpen=false;stockOpen=false;creationsTab=tab|| (state.studio.products.length?'production':'design');render(true);}
function resumeCraft(){if(speed===0){speed=presence(state).locked?state.life.awaySpeed:state.life.normalSpeed;lastSpeed=speed;idleClock.reset(performance.now());renderHeader();}}
function syncChrome(){const drawer=stockOpen||creationsOpen||pilotOpen||ordersOpen||!['atelier','build'].includes(view)||view==='build';document.body.dataset.drawer=drawer?'open':'closed';document.body.dataset.motion=state.settings.presentation.animation;const active=creationsOpen?'creations':['orders','marketing','finance'].includes(view)?view:'atelier';for(const b of document.querySelectorAll('.nav-item')){const on=b.dataset.view===active;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));}for(const b of document.querySelectorAll('[data-nav-badge]')){const n=b.dataset.navBadge==='orders'?metrics(state).requests:b.dataset.navBadge==='creations'?goodsFor(state):0;b.textContent=n;b.hidden=!n;}}
function openSettings(tab='realism'){const body=tab==='life'?lifeForm(state):tab==='sounds'?audioPanel(audio):tab==='saves'?savesPanel():realismForm(state);modal('Réglages de l’atelier',settingsTabs(tab)+body,true);}
function clickFeedback(button,event){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=button.getBoundingClientRect(),el=document.createElement('i');el.className='click-bloom';el.style.left=(event.clientX||rect.left+rect.width/2)+'px';el.style.top=(event.clientY||rect.top+rect.height/2)+'px';$('#click-effects').append(el);el.addEventListener('animationend',()=>el.remove(),{once:true});setTimeout(()=>el.remove(),700);}
function renderLife(){const p=presence(state);if((p.locked||p.kind==='remote')&&placement)cancelPlacement();$('#app').inert=false;document.body.classList.remove('life-locked');document.body.dataset.presence=p.kind;const shown=['sleep','away','remote'].includes(p.kind);$('#life-status').hidden=!shown;if(!shown)return;const next=clock(nextPresenceChange(state)),title=p.kind==='sleep'?'Ton artisan dort':p.kind==='remote'?'Télétravail · au bureau':'Emploi extérieur · au bureau',detail=p.kind==='sleep'?'Réveil à '+next.time:p.kind==='remote'?p.remaining+' min d’intervention disponibles':'Retour à '+next.time;paint('#life-status',`<span class="life-status-icon">${p.kind==='sleep'?'☾':'⌂'}</span><div><b>${title}</b><small>${detail} · atelier visible</small></div><button data-action="life" aria-label="Modifier mes horaires">⚙</button>`);}
document.addEventListener('submit',e=>{if(e.target.id!=='realism-form')return;e.preventDefault();const f=new FormData(e.target),values=Object.fromEntries(Object.keys(REALISM_LIMITS).map(k=>[k,Number(f.get(k))])),ranges={electricity:[.05,2],taxRate:[0,60],reserve:[0,100000],monthlyDraw:[0,10000]};for(const [k,[min,max]]of Object.entries(ranges)){const v=Number(f.get(k));if(!Number.isFinite(v)||v<min||v>max){$('#realism-error').textContent='Vérifie les valeurs de trésorerie et de tarif.';return;}}const result=setRealism(state,values);if(!result.ok){$('#realism-error').textContent=result.message;return;}for(const k of Object.keys(ranges))state.settings[k]=Number(f.get(k));state.settings.presentation=normalizePresentation({animation:f.get('animation')});act(result,'Réglages appliqués. Les achats déjà engagés gardent leur prix.');closeModal();});
document.addEventListener('submit',e=>{if(e.target.id!=='campaign-form')return;e.preventDefault();const v=new FormData(e.target);act(setCampaign(state,v.get('channel'),{budget:Number(v.get('budget')),days:Number(v.get('days')),target:v.get('target')}),'Campagne simulée lancée.');});
document.addEventListener('submit',e=>{if(e.target.id!=='product-project')return;e.preventDefault();const v=new FormData(e.target),result=setProjectDraft(state,v.get('name'),Number(v.get('price')));act(result,'Projet enregistré. La conception occupera les temps libres.');if(result.ok){closeModal();openCreations('design');resumeCraft();render(true);}});
document.addEventListener('submit',e=>{if(e.target.id!=='life-form')return;e.preventDefault();const f=e.target,v=new FormData(f),minute=k=>{const [h,m]=String(v.get(k)).split(':').map(Number);return h*60+m;},sleepStart=minute('sleepStart'),sleepEnd=minute('sleepEnd'),sleep=(sleepEnd-sleepStart+1440)%1440;if(sleep<240||sleep>720){$('#life-error').textContent='Prévois entre 4 et 12 heures de sommeil.';return;}if(minute('workEnd')<=minute('workStart')){$('#life-error').textContent='La fin du travail doit suivre le début dans la même journée.';return;}const first=!state.life.configured,previousSpeed=speed;state.life=normalizeLife({configured:true,mode:v.get('life-mode'),workStart:minute('workStart'),workEnd:minute('workEnd'),commute:Number(v.get('commute')),sleepStart,sleepEnd,workDays:[0,1,2,3,4,5,6].filter(d=>v.get('day-'+d)!=='off'),remoteDays:[0,1,2,3,4,5,6].filter(d=>v.get('day-'+d)==='remote'),remoteBudget:Number(v.get('remoteBudget')),workshopBudget:Number(v.get('workshopBudget')),normalSpeed:Number(v.get('normalSpeed')),awaySpeed:Number(v.get('awaySpeed')),autoSpeed:v.has('autoSpeed'),pauseOnReturn:v.has('pauseOnReturn'),backgroundProgress:v.has('backgroundProgress')});if(first&&state.objects.length===1&&state.metrics.completed===0&&state.time===510)state.time=sleepEnd;speed=first?(presence(state).locked&&state.life.autoSpeed?state.life.awaySpeed:state.life.normalSpeed):previousSpeed;lastSpeed=speed||state.life.normalSpeed;idleClock.reset(performance.now());closeModal();render(true);autosave();toast('Ton rythme est enregistré.','success');});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,p=presence(state);const permission=actionAvailability(state,a);if(!permission.ok){e.preventDefault();e.stopImmediatePropagation();toast(permission.message,'warning');return;}if(['pause','speed','skip','reset','restore'].includes(a))idleClock.reset(performance.now());clickFeedback(b,e);if(!['test-audio','sounds','cart-checkout'].includes(a))audio.play(a==='appearance-color'||a==='appearance-choice'?'wardrobe':a==='ship'?'ship':'click');
},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='idle-preset'){const enabled=!idleIsOn(state);act(setIdlePreset(state,enabled),enabled?'L’atelier suit tes consignes.':'Pilotage manuel.');if(enabled){speed=presence(state).locked?state.life.awaySpeed:state.life.normalSpeed;lastSpeed=speed;idleClock.reset(performance.now());}render(true);}
 else if(a==='skills')modal('Les savoir-faire de l’atelier.',`<div id="skills-live">${skillsPanel(state)}</div>`,true);
 else if(a==='learn-skill'){const result=learnSkill(state,id);act(result,'Nouveau savoir-faire acquis.');if(result.ok)modal('Les savoir-faire de l’atelier.',`<div id="skills-live">${skillsPanel(state)}</div>`,true);}
 else if(a==='machine-dashboard'){financeMode='machines';setView('finance');}
 else if(a==='finance-mode'){financeMode=b.dataset.mode;renderOther();}
 else if(a==='shop-mode'){shopMode=b.dataset.mode;renderOther();}
 else if(a==='inspect-machine'){setView('atelier');selected=id;ordersOpen=true;scene.setSelected(id);render(true);}
 else if(a==='creations-panel'){if(creationsOpen){creationsOpen=false;renderCreations();}else{if($('#modal').open)closeModal();openCreations();}}
 else if(a==='creations-tab'){creationsTab=b.dataset.tab;renderCreations();}
 else if(a==='start-creation'){const result=selectCreation(state,id);act(result,'Conception prévue pendant les temps disponibles.');if(result.ok)resumeCraft();}
 else if(a==='craft-restock'){const p=state.studio.products.find(p=>p.id===id);if(p){creationsOpen=false;pilotOpen=false;addBasket(p.material,productionPlan(state,id).colorId,1);}}
 else if(a==='craft-stock'){const result=queueProduction(state,id,Number(b.dataset.qty));act(result,'Fabrication prévue. Les commandes clients restent prioritaires.');if(result.ok)resumeCraft();}
 else if(a==='list-creation'){const result=setCreationListing(state,id,true);act(result,'La fiche produit sera préparée sur ton temps de travail.');if(result.ok)resumeCraft();}
 else if(a==='unlist-creation')act(setCreationListing(state,id,false),'Produit retiré des nouvelles demandes.');
 else if(a==='cancel-craft')act(cancelOrder(state,id),'Fabrication annulée.');
 else if(a==='pilot-panel'){const show=!pilotOpen;setView('atelier');pilotOpen=show;render(true);}
 else if(a==='project-draft')modal('Une création à toi.',projectForm(state));
 else if(a==='machine-compare')modal('Choisir sa machine.',compareMachines(),true);
 else if(a==='print-mode')act(setPrintMode(state,id,b.dataset.mode));
 else if(a==='energy')modal('L’électricité de l’atelier.',energyPanel(state)+energyProjection(state),true);
 else if(a==='pay-energy'){act(payEnergyBill(state,id),'Facture électrique réglée.');modal('L’électricité de l’atelier.',energyPanel(state)+energyProjection(state),true);}
 else if(a==='sounds')showSounds();
 else if(a==='test-audio'){audio.unlock().then(()=>{audio.lastEffect=-100;audio.lastNotice=-100;audio.play('complete');renderAudioStatus();});}
 else if(a==='life')showLife();
 else if(a==='quick-stock'){if(stockOpen){stockOpen=false;render(true);}else openStock();}
 else if(a==='quick-stock-close'){stockOpen=false;render(true);}
 else if(a==='stock-color'){draft.material=b.dataset.material;draft.colorId=b.dataset.color;openStock();}
 else if(a==='cart-material'){draft.material=b.dataset.material;render(true);}
 else if(a==='cart-color'){draft.colorId=b.dataset.color;render(true);}
 else if(a==='cart-qty'){draft.qty=Math.max(1,Math.min(12,draft.qty+Number(b.dataset.delta)));render(true);}
 else if(a==='cart-add')addBasket(draft.material,draft.colorId,draft.qty);
 else if(a==='add-needed')addBasket(b.dataset.material,b.dataset.color,Math.max(1,Math.ceil(Number(b.dataset.grams)/1000)));
 else if(a==='restock-needed')restock();
 else if(a==='cart-remove'){const line=basket.find(l=>l.item===b.dataset.material&&l.colorId===b.dataset.color);if(line&&--line.qty===0)basket=basket.filter(l=>l!==line);render(true);}
 else if(a==='cart-checkout'){const result=purchaseBasket(state,basket);if(result.ok){basket=[];audio.play('ship');act(result,'Livraison groupée commandée. Un seul port pour le panier.');}else act(result);}
 else if(a==='practice'){const result=practicePrinting(state);act(result,'Séance de calibration lancée.');if(result.ok){closeModal();speed=state.life.normalSpeed;idleClock.reset(performance.now());}}
 else if(a==='nav'){if($('#modal').open)closeModal();if(b.dataset.view==='creations')openCreations();else setView(b.dataset.view===view&&view!=='atelier'?'atelier':b.dataset.view);}
 else if(a==='character')character();
 else if(a==='appearance-color')updateAppearance(b.dataset.field,b.dataset.color);
 else if(a==='appearance-choice')updateAppearance(b.dataset.field,b.dataset.value);
 else if(a==='rotate-character')avatarPreview?.rotate();
 else if(a==='focus-person'){if(!scene.focusPerson())character();}
 else if(a==='toggle-orders'){const show=!ordersOpen;setView('atelier');ordersOpen=show;render(true);} else if(a==='pause'){if(speed){lastSpeed=speed;speed=0;}else{speed=lastSpeed||state.life.normalSpeed;state.autoPaused=false;}renderHeader();}
 else if(a==='speed'){speed=Number(b.dataset.speed);lastSpeed=speed;state.autoPaused=false;renderHeader();}
 else if(a==='skip'){const target=nextPresenceChange(state);advance(state,Math.max(1,target-state.time));if(state.autoPaused)speed=0;render(true);autosave();}
 else if(a==='guide')guide();else if(a==='settings')settings();else if(a==='settings-tab')openSettings(b.dataset.tab);else if(a==='realism-preset'){act(applyRealismPreset(state,id),'Profil appliqué aux prochaines opérations.');openSettings('realism');}else if(a==='save')autosave(true);else if(a==='close-modal')closeModal();
 else if(a==='buy-mode')beginPlacement(b.dataset.type);
 else if(a==='cancel-placement'){cancelPlacement();renderShop();}
 else if(a==='rotate-object'){rot=(rot+1)%4;scene.rotatePlacement();}
 else if(a==='open-grid'||a==='fallback-grid')gridModal();
 else if(a==='grid-rotate'){rot=(rot+1)%4;scene.rotatePlacement();gridModal();}
 else if(a==='grid-place'){const x=Number(b.dataset.x),z=Number(b.dataset.z),r=moveId?moveObject(state,moveId,x,z,rot):buyObject(state,placement,x,z,rot);if(r.ok){const chosen=r.object?.id||moveId;setView('atelier');ordersOpen=true;selected=chosen;scene.setSelected(selected);closeModal();cancelPlacement();render(true);autosave();toast('Équipement installé.','success');}else toast(r.message,'warning');}
 else if(a==='select'){ordersOpen=true;selected=id;scene.setSelected(id);renderRight();renderEquipmentStrip();}
 else if(a==='deselect'){setView('atelier');render(true);}
 else if(a==='move'){const o=state.objects.find(o=>o.id===id);if(o)beginPlacement(o.type,id);}
 else if(a==='sell'){act(sellObject(state,id),'Équipement revendu.');if(!state.objects.some(o=>o.id===selected)){selected=null;scene.setSelected(null);render(true);}}
 else if(a==='service')act(serviceMachine(state,id));else if(a==='part')act(serviceMachine(state,id,b.dataset.part));
 else if(a==='accept'){act(acceptOrder(state,id),'Commande confirmée.');rightTab='active';ordersOpen=true;renderRight();}
 else if(a==='decline'){declineOrder(state,id);render(true);autosave();}
 else if(a==='cancel-order'){modal('Annuler cette commande ?',`<p class="modal-lead">La matière déjà consommée est perdue. Une commande confirmée puis annulée crée un avis défavorable.</p><div class="modal-actions"><button class="button ghost" data-action="close-modal">La conserver</button><button class="button danger-button" data-action="cancel-confirm" data-id="${id}">Annuler la commande</button></div>`);}
 else if(a==='cancel-confirm'){act(cancelOrder(state,id),'Commande annulée.');closeModal();}
 else if(a==='ship')act(shipOrder(state,id),state.orders.find(o=>o.id===id)?.channel==='local'?'Retrait prévu au prochain créneau ouvré de 17 h.':'Bordereau créé. Collecte au prochain passage ouvré.');
 else if(a==='right-tab'){rightTab=b.dataset.tab;renderRight();}else if(a==='show-active'){rightTab='active';selected=null;ordersOpen=true;renderRight();}
 else if(a==='supply')act(purchaseSupply(state,b.dataset.kind,b.dataset.item),'Approvisionnement commandé.');
 else if(a==='campaign')act(setCampaign(state,b.dataset.channel),'Consigne de communication mise à jour.');
 else if(a==='website')act(launchWebsite(state),'Création de la boutique ajoutée au travail personnel.');
 else if(a==='rotate-camera')scene.rotate();else if(a==='zoom-in')scene.zoomBy(-1);else if(a==='zoom-out')scene.zoomBy(1);else if(a==='reset-camera')scene.resetCamera();else if(a==='grid')scene.toggleGrid();
 else if(a==='export'){autosave();download('filament-partie-jour-'+(dayOf(state.time)+1)+'.json',exportSave(state));toast('Export JSON préparé.','success');}
 else if(a==='import')$('#import-file').click();
 else if(a==='export-ledger'){const rows=[['Jour','Heure','Mouvement','Categorie','Montant'],...state.cashLedger.map(r=>[dayOf(r.at)+1,clock(r.at).time,r.label,CASH_LABELS[r.kind]||r.kind,r.amount.toFixed(2).replace('.',',')])];download('filament-journal-de-caisse.csv','\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');}
 else if(a==='reset-confirm')modal('Recommencer l’aventure ?',`<p class="modal-lead">Tu repartiras avec 1 500 €, une pièce disponible et trois premières demandes. Une copie de la partie actuelle sera conservée sur cet appareil.</p><div class="modal-actions"><button class="button ghost" data-action="close-modal">Garder ma partie</button><button class="button danger-button" data-action="reset">Nouvelle partie</button></div>`);
 else if(a==='reset'){try{localStorage.setItem(SAVE_KEY+':before-reset',exportSave(state));state=createState();presentation.reset(state,performance.now());selected=null;scene.setSelected(null);scene.lastSignature='';cancelPlacement();speed=0;closeModal();setView('atelier');autosave();toast('Nouvelle partie.','success');showLife(true);}catch{toast('Reset arrêté : la copie de secours ne peut pas être sauvegardée. Exporte ta partie.','warning');}}
 else if(a==='restore'){try{const raw=localStorage.getItem(SAVE_KEY+':before-reset');if(!raw)throw Error('Aucune partie de secours disponible.');state=importSave(raw);presentation.reset(state,performance.now());selected=null;cancelPlacement();scene.setSelected(null);scene.lastSignature='';closeModal();setView('atelier');autosave();toast('Partie précédente restaurée.','success');}catch(e){toast(e.message,'warning');}}
});
document.addEventListener('input',e=>{if(e.target.dataset.audio){audio.set(e.target.dataset.audio,e.target.type==='checkbox'?e.target.checked:Number(e.target.value));const out=document.querySelector('[data-audio-output="'+e.target.dataset.audio+'"]');if(out)out.textContent=e.target.value+' %';return;}if(e.target.matches('[data-appearance="name"]'))updateAppearance('name',e.target.value);});
document.addEventListener('change',e=>{const el=e.target,key=el.dataset.setting;if(el.matches('[data-speed-choice]')){speed=Number(el.value);lastSpeed=speed;state.autoPaused=false;idleClock.reset(performance.now());renderHeader();return;}
 if(el.dataset.productVisible){act(setProductVisibility(state,el.dataset.productVisible,el.checked));return;}
 if(el.dataset.productFeatured){const result=featureProduct(state,el.dataset.productFeatured,el.checked);if(!result.ok)el.checked=false;act(result);return;}
 if(el.dataset.productChannel){act(setProductChannel(state,el.dataset.productChannel,el.dataset.channel,el.checked));return;}

 if(el.dataset.productionColor){act(setProductionPlan(state,el.dataset.productionColor,{colorId:el.value}));return;}
 if(el.dataset.productionTarget){act(setProductionPlan(state,el.dataset.productionTarget,{target:Number(el.value)}));return;}
 if(el.dataset.productionAuto){act(setProductionPlan(state,el.dataset.productionAuto,{enabled:el.checked}));return;}
 if(el.dataset.creationPrice){const result=setCreationPrice(state,el.dataset.creationPrice,Number(el.value));act(result);if(!result.ok)el.value=state.studio.products.find(p=>p.id===el.dataset.creationPrice)?.price;return;}
 if(el.dataset.creationOndemand){act(setCreationOnDemand(state,el.dataset.creationOndemand,el.checked));return;}
if(el.matches('[data-idle-mode]')){act(setIdleMode(state,el.value));return;}if(el.dataset.audio){audio.set(el.dataset.audio,el.type==='checkbox'?el.checked:Number(el.value));return;}if(el.name==='life-mode'){$('#employment-fields').hidden=el.value==='fulltime';return;}if(el.dataset.appearance){updateAppearance(el.dataset.appearance,el.type==='checkbox'?el.checked:el.value);return;}if(!key)return;if(el.type==='checkbox')state.settings[key]=el.checked;else{const ranges={reserve:[0,100000],monthlyDraw:[0,10000],taxRate:[0,60],electricity:[.05,2]};const [min,max]=ranges[key]||[0,100000],value=Number(el.value);if(Number.isFinite(value))state.settings[key]=Math.max(min,Math.min(max,value));el.value=state.settings[key];}if(key==='useEtsy'&&!state.settings.useEtsy&&state.campaign.channel==='etsy')setCampaign(state,'none');if(key==='useLocal'&&!state.settings.useLocal&&state.campaign.channel==='local')setCampaign(state,'none');render(true);autosave();});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Le fichier dépasse 8 Mo.');const imported=importSave(await file.text());try{localStorage.setItem(SAVE_KEY+':before-reset',exportSave(state));}catch{}state=imported;presentation.reset(state,performance.now());idleClock.reset(performance.now());selected=null;scene.setSelected(null);scene.lastSignature='';cancelPlacement();speed=0;closeModal();setView('atelier');autosave();toast('Sauvegarde importée. Le temps est en pause.','success');if(!state.life.configured)showLife(true);}catch(err){toast('Import impossible : '+err.message,'warning');}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key.toLowerCase()==='m'){audio.set('enabled',!audio.prefs.enabled);return;}if(presence(state).locked&&e.code!=='Space'&&e.key!=='Escape')return;if(e.key==='Escape')cancelPlacement();if(e.key.toLowerCase()==='r'&&placement){rot=(rot+1)%4;scene.rotatePlacement();}if(e.code==='Space'&&!e.target.closest('button,summary')&&!$('#modal').open){e.preventDefault();idleClock.reset(performance.now());if(speed){lastSpeed=speed;speed=0;}else speed=lastSpeed;renderHeader();}});
const idleClock=new IdleClock({getState:()=>state,advance,getSpeed:()=>speed,setSpeed:value=>{speed=value;lastSpeed=value||state.life.normalSpeed;},onReturn:paused=>{if(paused){audio.play('complete');toast('Te voilà disponible. La pause au retour est activée.','success');}},onCritical:()=>toast('Trésorerie critique : temps en pause. Consulte Les comptes.','warning')});
function heartbeat(now){idleClock.tick(now,{hidden:document.hidden});if(now-lastSave>20000){lastSave=now;autosave();}}
document.addEventListener('visibilitychange',()=>{if(!state.life.backgroundProgress)idleClock.reset(performance.now());else heartbeat(performance.now());audio.setHidden(document.hidden);if(document.hidden)autosave();else render(true);});
window.addEventListener('pagehide',()=>{heartbeat(performance.now());autosave();});
setInterval(()=>{if(document.hidden)heartbeat(performance.now());},1000);
function frame(now){
 heartbeat(now);
 if(!document.hidden&&now-lastRender>350){lastRender=now;if($('#modal').open)renderHeader();else render();const p=presence(state);audio.update({playing:speed>0,busy:printers(state).filter(m=>m.job&&!m.broken&&!m.paused&&(state.settings.nightPrinting||p.canWork)).length,working:p.canWork&&!!state.worker},state);}
 requestAnimationFrame(frame);
}
idleClock.reset(performance.now());render(true);requestAnimationFrame(frame);if(saveError)toast(saveError,'warning');if(!state.life.configured)showLife(true);else{speed=0;lastSpeed=presence(state).locked&&state.life.autoSpeed?state.life.awaySpeed:state.life.normalSpeed;renderHeader();}
